$manifest=[ordered]@{schemaVersion=1;manifestKind='gate13r-36h-attempt7-preimplementation-static-partial-manifest-v1';createdAtUtc=[DateTime]::UtcNow.ToString('o');status='FAILED-PRE-ROOT';files=$files.ToArray();verificationRootCreated=Test-Path $verification;pilotRootCreated=Test-Path $pilot;cloneRootCreated=Test-Path $clone;formalRootCreated=Test-Path $formal;unityProcessCount=@(Get-Process Unity -ErrorAction SilentlyContinue).Count;pilotStarted=$false;formalCampaign=$false;passed=$false};AtomicJson $manifestPath $manifest
